下面是一个通用的 `buildMqttConnect` 函数,并给出该参数的最终字节数组。

## 报文结构拆解

| 区域 | 内容 | 字节 |
|------|------|------|
| Fixed Header | `0x10` (CONNECT) + 剩余长度 `0x14` (20) | 2 |
| Variable Header | 协议名长度 `0x00 0x04` + `'MQTT'` + 协议级别 `0x04` + 连接标志 `0x02` + KeepAlive `0x00 0x3C` | 10 |
| Payload | ClientId 长度 `0x00 0x08` + `'test-123'` | 10 |

连接标志 `0x02` = `0000 0010`,Bit1 Clean Session = 1,其余位全 0。

## Node.js 函数

```javascript
function buildMqttConnect({
  clientId   = 'test-123',
  keepalive  = 60,
  clean      = true,
  protocolName  = 'MQTT',
  protocolLevel = 4,   // 3.1.1
} = {}) {
  // ===== Variable Header =====
  const proto   = Buffer.from(protocolName);                       // 'MQTT'
  const vh = Buffer.concat([
    Buffer.from([0x00, proto.length]), proto,                      // 协议名 + 长度前缀
    Buffer.from([protocolLevel]),                                  // 协议级别
    Buffer.from([clean ? 0x02 : 0x00]),                            // Connect Flags
    Buffer.from([(keepalive >> 8) & 0xff, keepalive & 0xff]),      // Keep Alive(大端)
  ]);

  // ===== Payload =====
  const cid = Buffer.from(clientId);
  const pl  = Buffer.concat([
    Buffer.from([0x00, cid.length]),
    cid,
  ]);

  // ===== Remaining Length (MQTT 可变长编码,这里长度<128,用 1 字节) =====
  const remLen = vh.length + pl.length;                            // = 20
  const rem    = Buffer.from([remLen & 0x7f]);

  // ===== Fixed Header =====
  return Buffer.concat([Buffer.from([0x10]), rem, vh, pl]);
}

const pkt = buildMqttConnect();
console.log(Buffer.from([...pkt]));
console.log('总字节数 =', pkt.length);   // 22
```

## 期望的字节数组(按你的要求输出)

```javascript
Buffer.from([
  0x10, 0x14,                                      // Fixed Header: CONNECT, 剩余长度 20
  0x00, 0x04, 0x4D, 0x51, 0x54, 0x54,              // 协议名长度=4, "MQTT"
  0x04,                                            // 协议级别 (MQTT 3.1.1)
  0x02,                                            // Connect Flags: Clean Session = 1
  0x00, 0x3C,                                      // Keep Alive = 60
  0x00, 0x08,                                      // ClientId 长度 = 8
  0x74, 0x65, 0x73, 0x74, 0x2D, 0x31, 0x32, 0x33,  // "test-123"
])
```

总共 **22 字节**。如果你有现成的 broker(例如 mosquitto),可以直接 `client.write(pkt)` 发送这条 CONNECT 报文进行验证。

# MQTT 3.1.1 PUBLISH 报文构造 (QoS 0)

## 报文结构分析

```
┌─────────┬──────────┬──────────────┬─────────┐
│ Fixed Header  │ Variable Header │ Payload │
│ Type+Flags │RemLen│ Topic Len │ Topic  │ Data   │
│  0x30     │ 0x0E │ 0x00 0x07 │ foo/bar│ hello  │
└─────────┴──────────┴──────────────┴─────────┘
```

- **Byte 1**: `0x30` = `0011 0000` → 类型 PUBLISH(3)<<4 | flags `0000` (DUP=0, QoS=0, RETAIN=0)
- **Byte 2**: `0x0E` = 14 (2 + 7 + 5 = 剩余长度)
- **Topic Length**: `0x00 0x07` (大端, 7 字节)
- **QoS 0 不需要 Packet Identifier**
- **Payload**: 直接跟 Application Data

## 函数实现

```js
/**
 * 构造一个 MQTT 3.1.1 PUBLISH 报文
 * QoS 0, DUP 0, RETAIN 0
 * Topic: foo/bar
 * Payload: hello
 */
function buildMqttPublishQos0() {
  return Buffer.from([
    0x30,                          // 固定头第 1 字节: PUBLISH(3)<<4 | flags=0
    0x0E,                          // 剩余长度 = 2(topic len) + 7(topic) + 5(payload) = 14
    0x00, 0x07,                    // Topic Name 长度 (大端)
    0x66, 0x6F, 0x6F, 0x2F,        // "foo"
    0x62, 0x61, 0x72,              // "bar"
    0x68, 0x65, 0x6C, 0x6C, 0x6F   // "hello"
  ]);
}

// 验证
const packet = buildMqttPublishQos0();
console.log(packet.toString('hex'));
// 期望输出: 300e0007666f6f2f62617268656c6c6f
```

## 验证输出

```
30 0e 00 07 66 6f 6f 2f 62 61 72 68 65 6c 6c 6f
```

## 可参数化的通用版本

如果你想让函数接受参数, 注意 **QoS > 0 时需要插入 Packet Identifier**:

```js
function buildMqttPublish({ topic, payload, qos = 0, dup = 0, retain = 0 }) {
  const topicBuf = Buffer.from(topic);
  const payloadBuf = Buffer.from(payload);
  const hasPacketId = qos > 0;

  // 剩余长度
  let remLen = 2 + topicBuf.length + payloadBuf.length;
  if (hasPacketId) remLen += 2;

  // 第 1 字节: (3 << 4) | (dup << 3) | (qos << 1) | retain
  const byte1 = 0x30 | ((dup & 1) << 3) | ((qos & 3) << 1) | (retain & 1);

  // 组装: 固定头 + 长度字节 + topic len(2) + topic + [packetId(2)] + payload
  const parts = [Buffer.from([byte1, remLen]), packMsb(topicBuf.length), topicBuf];
  if (hasPacketId) parts.push(packMsb(0x0001)); // QoS>0 时需要 PID
  parts.push(payloadBuf);

  return Buffer.concat(parts);
}

function packMsb(n) { return Buffer.from([(n >> 8) & 0xff, n & 0xff]); }
```

注意: 上述通用版本中 `packMsb` 仅当 `remLen < 128` 时固定长度算法可用, 真实生产中应使用**变长编码 (Variable Length)** 写剩余长度字段。

# MQTT 3.1.1 SUBSCRIBE 报文构造

## 报文结构分析

SUBSCRIBE 报文由三部分组成：

| 部分 | 内容 | 字节数 |
|------|------|--------|
| Fixed Header | `0x82` (类型 8 + 标志 0010) + Remaining Length | 2 |
| Variable Header | Packet Identifier = 1 | 2 |
| Payload | Topic Filter `'foo/+'` + QoS = 1 | 8 |
| **合计** | | **12** |

## 实现代码

```javascript
function buildSubscribePacket(packetId, topic, qos) {
  // 1. Packet Identifier (2 bytes, big-endian)
  const packetIdBytes = Buffer.from([(packetId >> 8) & 0xFF, packetId & 0xFF]);

  // 2. Topic Filter: UTF-8 长度前缀 + 字符串字节
  const topicBytes = Buffer.from(topic, 'utf8');                // "foo/+"
  const topicLengthBytes = Buffer.from([
    (topicBytes.length >> 8) & 0xFF,
    topicBytes.length & 0xFF
  ]);

  // 3. Requested QoS (1 byte)
  const qosByte = Buffer.from([qos & 0x03]);

  // 拼接 Variable Header + Payload
  const varHeaderAndPayload = Buffer.concat([
    packetIdBytes,        // 0x00 0x01
    topicLengthBytes,     // 0x00 0x05
    topicBytes,           // "foo/+"
    qosByte               // 0x01
  ]);

  // 4. Fixed Header
  //    高 4 位 = 1000 (SUBSCRIBE = 8)
  //    低 4 位 = 0010 (SUBSCRIBE 保留标志，必须为 0010)
  //    => 0x82
  // Remaining Length = 10, 1 字节即可
  const fixedHeader = Buffer.from([0x82, varHeaderAndPayload.length]);

  return Buffer.concat([fixedHeader, varHeaderAndPayload]);
}

// === 使用 ===
const packet = buildSubscribePacket(1, 'foo/+', 1);
console.log('Hex :', packet.toString('hex').toUpperCase());
console.log('Bytes:', [...packet].map(b => '0x' + b.toString(16).padStart(2, '0')));
```

## 输出验证

```
Hex : 820A0001000566 6F6F 2F2B 01
Bytes: 0x82, 0x0A, 0x00, 0x01, 0x00, 0x05, 0x66, 0x6F, 0x6F, 0x2F, 0x2B, 0x01
```

逐字节解析：

```
0x82              ← Fixed Header 第 1 字节: 1000 0010 (SUBSCRIBE, flags=0010)
0x0A              ← Remaining Length = 10
0x00 0x01         ← Packet Identifier = 1
0x00 0x05         ← Topic Filter 长度 = 5
0x66 0x6F 0x6F    ← "foo"
0x2F 0x2B         ← "/+"
0x01              ← Requested QoS = 1
```

## 关键细节说明

1. **固定头低 4 位必须为 `0010`**：MQTT 3.1.1 规定 SUBSCRIBE 报文的标志位固定为 `0010`，所以完整字节是 `0x82`（而不是 `0x80`）。

2. **Remaining Length = 10**：Variable Header (2) + Payload (2 + 5 + 1) = 10。因为 10 < 128，只需 1 字节编码。若 ≥ 128 则需要用可变字节整数（每个字节低 7 位为值，最高位 1 表示续接）。

3. **UTF-8 字符串长度**：使用大端 2 字节表示，`'foo/+'` 长度为 5 → `0x00 0x05`。

4. **Packet Identifier 大端序**：`packetId=1` → `0x00 0x01`（高字节在前），不是 `0x01 0x00`。

# 构造 MQTT 3.1.1 SUBSCRIBE 报文

## 报文结构拆解

| 部分 | 内容 | 字节 |
|------|------|------|
| 固定头 | `0x82` (type=8, flags=0b0010) | 1 |
| 剩余长度 | `0x0A` (10 字节) | 1 |
| Packet ID | `0x00 0x01` | 2 |
| Topic 长度 | `0x00 0x05` | 2 |
| Topic | `foo/+` | 5 |
| QoS | `0x01` | 1 |

## 实现

```javascript
function buildSubscribePacket(packetId = 1, topic = 'foo/+', qos = 1) {
  // 1. 校验 QoS (MQTT 3.1.1 中 SUBSCRIBE 的 QoS 只能是 0 或 1)
  if (qos !== 0 && qos !== 1) {
    throw new Error('SUBSCRIBE QoS must be 0 or 1');
  }

  // 2. 编码 topic
  const topicBuf = Buffer.from(topic, 'utf8');

  // 3. 构造 可变头 + 负载
  //    格式: PacketId(2) + TopicLen(2) + Topic(N) + QoS(1)
  const vh = Buffer.alloc(2 + 2 + topicBuf.length + 1);
  vh.writeUInt16BE(packetId, 0);          // Packet ID (大端)
  vh.writeUInt16BE(topicBuf.length, 2);   // Topic 长度
  topicBuf.copy(vh, 4);                   // Topic 内容
  vh[4 + topicBuf.length] = qos;          // 请求的 QoS

  // 4. 剩余长度编码 (此处 ≤127, 1 字节即可; 真实实现需按 MQTT 可变长度编码处理)
  const remainingLen = vh.length;
  const lenBytes = [];
  let x = remainingLen;
  do {
    let encodedByte = x % 128;
    x = Math.floor(x / 128);
    if (x > 0) encodedByte |= 0x80;
    lenBytes.push(encodedByte);
  } while (x > 0);

  // 5. 固定头: 0x82 = (type=8)<<4 | flags=0b0010
  //    SUBSCRIBE 的 flags 必须为 0010, 低 4 位 = 2
  const fixed = Buffer.from([0x82, ...lenBytes]);

  return Buffer.concat([fixed, vh]);
}

// --- 测试 ---
const packet = buildSubscribePacket();
console.log(packet);
// => <Buffer 82 0a 00 01 00 05 66 6f 6f 2f 2b 01>
console.log([...packet].map(b => '0x' + b.toString(16).padStart(2, '0')));
// => [ '0x82', '0x0a', '0x00', '0x01', '0x00', '0x05',
//      '0x66', '0x6f', '0x6f', '0x2f', '0x2b', '0x01' ]
```

## 字节级验证

```
0x82  0x0a  0x00 0x01  0x00 0x05  0x66 0x6f 0x6f 0x2f 0x2b  0x01
 ^     ^     ^^^^^^^^  ^^^^^^^^  ^^^^^^^^^^^^^^^^^^^^^^^   ^^^^
 |     |     PacketId   TopicLen       "foo/+"            QoS
 |     |
 |     Remaining Length = 10
 |
 Fixed Header: type=8(SUBSCRIBE) | flags=0b0010
```

> ⚠️ **小提示**: 真实生产代码应处理 **剩余长度 > 127** 的情况(需用最多 4 字节的可变长度编码, 每字节高位置 1 作为延续位)。上面循环里用 `do/while` 写的就是标准 MQTT 变长整数编码,即使 `remainingLen` 很大也能正确工作。

```javascript
/**
 * 返回 MQTT 3.1.1 PINGREQ 报文。
 * 固定头部: 0xC0 (PINGREQ 控制报文类型 + flags=0) + 0x00 (剩余长度 = 0)
 *
 * @returns {Buffer} 长度为 2 的 Buffer
 */
function buildPingreqPacket() {
  return Buffer.from([0xC0, 0x00]);
}

// 简单验证
const pkt = buildPingreqPacket();
console.log(pkt);              // <Buffer c0 00>
console.log(pkt.length);       // 2
console.log(pkt.toString('hex')); // "c000"

// 报文结构说明:
// Byte 1: 0xC0  ->  0b1100_0000
//                  ^^^^      控制报文类型 = 12 (PINGREQ)
//                      ^^^^  标志位 = 0
// Byte 2: 0x00  ->  剩余长度 = 0 (PINGREQ 无可变头部、无载荷)
```

如果想做得更通用一些，可以扩展为同时支持 PINGRESP：

```javascript
/**
 * 根据类型返回 PINGREQ / PINGRESP 报文。
 * @param {'req'|'resp'} kind
 */
function buildPingPacket(kind = 'req') {
  const type = kind === 'resp' ? 0xD0 : 0xC0; // PINGRESP=13, PINGREQ=12
  return Buffer.from([type, 0x00]);
}
```

说明:
- MQTT 控制报文类型占高 4 位，所以 PINGREQ = `12 << 4 = 0xC0`，PINGRESP = `13 << 4 = 0xD0`。
- 剩余长度字段固定为 `0x00`，因为这两个报文都没有可变报头和有效载荷。

# MQTT 3.1.1 PINGREQ 报文生成函数

## 报文结构说明

PINGREQ 是 MQTT 3.1.1 协议中**最简单的控制报文**,固定 2 字节:

| 字节 | 值 | 含义 |
|------|------|------|
| Byte 1 | `0xC0` | 固定报头第 1 字节 |
| Byte 2 | `0x00` | 剩余长度 = 0 |

**`0xC0` 拆分:**
- 高 4 位 `1100` → 报文类型 = **12** (PINGREQ)
- 低 4 位 `0000` → 标志位 = 0 (保留)

**`0x00`:** 剩余长度字段为 0,表示 PINGREQ 没有可变报头和有效载荷。

---

## 函数实现

```javascript
/**
 * 构造 MQTT 3.1.1 PINGREQ 报文 (心跳请求)
 * @returns {Buffer} 长度为 2 的 Buffer: [0xC0, 0x00]
 */
function buildPingReqPacket() {
  // 0xC0 = 报文类型 PINGREQ (12) << 4 | 标志位 0
  // 0x00 = 剩余长度 (无可变报头/载荷)
  return Buffer.from([0xC0, 0x00]);
}
```

---

## 使用示例

```javascript
const mqtt = require('mqtt');
const client = mqtt.connect('mqtt://broker.emqx.io:1883');

client.on('connect', () => {
  // 1. 直接发送 PINGREQ 报文
  const pingReq = buildPingReqPacket();
  console.log('报文长度:', pingReq.length);  // 2
  console.log('报文十六进制:', pingReq.toString('hex')); // "c000"

  // 2. 通过 socket 发送 (跳过协议库,直接发原始字节)
  const net = require('net');
  const socket = net.connect(1883, 'broker.emqx.io', () => {
    socket.write(pingReq);
  });

  // 期望服务端返回 0xD0 0x00 (PINGRESP)
  socket.on('data', (data) => {
    if (data[0] === 0xD0 && data[1] === 0x00) {
      console.log('✓ 收到 PINGRESP,心跳保活成功');
    }
  });
});
```

---

## 对照:其它报文格式参考

为方便对比,展示常见控制报文的首字节:

| 报文类型 | 首字节 | 剩余长度 |
|---------|--------|---------|
| CONNECT  | `0x10` | 变长    |
| PUBLISH  | `0x30` (QoS 0) | 变长 |
| PUBACK   | `0x40` | 2       |
| **PINGREQ**  | **`0xC0`** | **0** |
| PINGRESP | `0xD0` | 0       |
| DISCONNECT | `0xE0` | 0     |

PINGREQ 之所以能做到 2 字节定长,是因为它**不携带任何客户端标识、心跳间隔或载荷数据**——仅用于告知 Broker "我还活着"。
